import itertools
from scipy.optimize import least_squares
fams={
 'pow_eps': lambda e,p: e**p,
 'exp_eps': lambda e,p: np.exp(-p*e),
 'cos_eps': lambda e,p: np.cos(p*e),
 'sin_eps': lambda e,p: np.sin(p*e),
 'tanh_eps': lambda e,p: np.tanh(p*e),
 'log_eps': lambda e,p: np.log(1+p*e),
 'eps_exp': lambda e,p: e*np.exp(-p*e),
 'sqrt_eps2': lambda e,p: np.sqrt(e**2+p),
}
gams={
 'T': lambda t,q: t**q,
 'exp_T': lambda t,q: np.exp(-q*t),
 'tanh_T': lambda t,q: np.tanh(q*t),
 'cos_T': lambda t,q: np.cos(q*t),
 'sin_T': lambda t,q: np.sin(q*t),
 'exp_T2': lambda t,q: np.exp(-q*t*t),
 'lin': lambda t,q: t+q,
 'inv': lambda t,q: 1/(t+q),
}
res_list=[]
for (fn,f),(gn,g) in itertools.product(fams.items(),gams.items()):
    def mdl(p):
        return p[0]+p[1]*np.tanh(p[2]*T)+p[3]*np.exp(-p[4]*T)*eps**2+p[5]*f(eps,p[6])*g(T,p[7])
    best=None
    for s in range(4):
        p0=np.random.default_rng(s).normal(size=8)
        try:
            rr=least_squares(lambda p: mdl(p)-sigma,p0,max_nfev=300)
            if np.all(np.isfinite(rr.fun)) and (best is None or rr.cost<best.cost): best=rr
        except Exception: pass
    if best is not None: res_list.append((best.cost,fn,gn,np.round(best.x,4)))
res_list.sort(key=lambda z:z[0])
for z in res_list[:8]: print(z)

